B.Ce={"NoveraFlow \ub3d9\uae30\ud654 \uc2dc\ud5d8":0,"NoveraFlow \uc6f9":1,"\ud648":2,"\uba54\ubaa8":3,"\uae30\ub85d":4,"\ub9c8\uc74c\uacb0":5,"\uac80\uc0c9":6,"\uc124\uc815":7,"\uc571":8,"\ub85c\uadf8\uc544\uc6c3":9,"\uc624\ub298\uc758 \uae30\ub85d":10,"\ud55c \uc904\uc774\uc5b4\ub3c4 \ucda9\ubd84\ud574\uc694.":11,"\ub098\uc758 \uc18d\ub3c4\ub85c, \ucc28\ubd84\ud558\uac8c \uc774\uc5b4\uac00\uc694.":12,[u.o]:13,"\uaca9\ub9ac \uac1c\ubc1c \ud654\uba74\uc785\ub2c8\ub2e4. \uc571 \uae30\ub85d \ub3d9\uae30\ud654\ub294 \uc81c\uacf5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.":14,[u.M]:15,"\uc778\uc99d \uc11c\ube44\uc2a4\uc5d0 \uacc4\uc815\uc744 \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.":16,"\ub85c\uadf8\uc544\uc6c3 \uc0c1\ud0dc\uc785\ub2c8\ub2e4.":17,"\uc778\uc99d \uc11c\ube44\uc2a4\uc5d0\uc11c \uacc4\uc815\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.":18,"\uacc4\uc815\uc744 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ub2e4\uc2dc \ub85c\uadf8\uc778\ud574 \uc8fc\uc138\uc694.":19,[u.L]:20,"\uc2dc\ud5d8 \uc778\uc99d \uc124\uc815\uacfc \uc6f9 \ucf5c\ubc31 \ud5c8\uc6a9 \uc5ec\ubd80\ub97c \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.":21,"\uc6f9 \uc5f0\uacb0\uc744 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc7a0\uc2dc \ud6c4 \uc0c8\ub85c\uace0\uce68\ud574 \uc8fc\uc138\uc694.":22,"\ub098\uc758 \uae30\ub85d\uc744 \uc774\uc5b4\uc11c":23,[u.H]:24,"Google\ub85c \ub85c\uadf8\uc778":25,"Apple\ub85c \ub85c\uadf8\uc778":26,"\uacc4\uc815 \ub2e4\uc2dc \ud655\uc778":27,[u.n]:28,"\uae30\ub85d\uacfc \ub3d9\uae30\ud654":29,[u.F]:30,"\ubc31\uc5c5\xb7\ubcf5\uad6c":31,[u._]:32,[u.u]:33,[u.X]:34,"\uae30\ub85d\uc73c\ub85c \ub3cc\uc544\uac00\uae30":35,"\uc218\uc815 \uc911\uc778 \ub0b4\uc6a9\uc774 \uc788\uc2b5\ub2c8\ub2e4":36,"\ub2e4\ub978 \uae30\ub85d\uc744 \uc5f4\uba74 \uc800\uc7a5\ud558\uc9c0 \uc54a\uc740 \ub0b4\uc6a9\uc774 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4.":37,"\uacc4\uc18d \uc218\uc815":38,"\ub2e4\ub978 \uae30\ub85d \uc5f4\uae30":39,"\ud55c \uc904 \ub0a8\uae30\uae30":40,"\uae30\ub85d \uc218\uc815":41,"\uc0c8 \uae30\ub85d \uc791\uc131 \uc911":42,"\uae30\ub85d \uc218\uc815 \uc911":43,"\uae30\ubcf8 \uc0c1\uc9d5":44,"\uc120\ud0dd \uc548 \ud568":45,"\uc0c1\uc9d5 \uc5c6\uc74c":46,[u.I]:47,[u.G]:48,"\uc0c1\uc9d5\ub9cc \ub418\ub3cc\ub9ac\uae30":49,"\uae30\uc874 \uc120\ud0dd \ubb38\uad6c\uc640 \uba54\ubaa8\ub294 \uadf8\ub300\ub85c \ubcf4\uc874\ub429\ub2c8\ub2e4.":50,"\ubcf8\ubb38":51,"\uc9c0\uae08 \ub9c8\uc74c\uc5d0 \ub0a8\uc740 \ud55c \uc904\uc744 \uc801\uc5b4\ubcf4\uc138\uc694.":52,"\ub3d9\uae30\ud654\ud558\ub824\uba74 \ubcf8\ubb38\uc744 \uc785\ub825\ud574 \uc8fc\uc138\uc694.":53,"\uae30\uae30\uc5d0 \uc800\uc7a5\xb7\ub3d9\uae30\ud654":54,"\uc800\uc7a5":55,"\uac19\uc740 \uc694\uccad \uc7ac\uc2dc\ub3c4":56,"\uc0c8 \uae30\ub85d \uc791\uc131":57,"\ubcf8\ubb38 \uac80\uc0c9":58,"\uae30\uc5b5\ud558\uace0 \uc2f6\uc740 \ud55c \uc904 \ucc3e\uae30":59,"\uac80\uc0c9\xb7\uc0c8\ub85c\uace0\uce68":60,[u.Z]:61,"\uac80\uc0c9 \uacb0\uacfc":62,"\ub0b4 \uae30\ub85d":63,"\uc544\uc9c1 \ud45c\uc2dc\ud560 \uae30\ub85d\uc774 \uc5c6\uc5b4\uc694. \ud55c \uc904\ubd80\ud130 \uc2dc\uc791\ud574 \ubcf4\uc138\uc694.":64,"\ub354 \ubcf4\uae30":65,"\uae30\ub85d \uc815\ubcf4":66,"\uc0c1\uc9d5":67,"\uc804\uc1a1 \ub300\uae30":68,"\ucda9\ub3cc \ubcf4\uc874":69,"\uac1c\uc758 \uae30\ub85d":70,"\uc791\uc131 \uc2dc\uac01":71,"\uc120\ud0dd \ubb38\uad6c":72,"\uc11c\ubc84 \uae30\ub85d\uc744 \uc870\ud68c\ud588\uc2b5\ub2c8\ub2e4.":73,"\uc870\ud68c\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc785\ub825\uc740 \ubcf4\uc874\ud588\uc2b5\ub2c8\ub2e4.":74,[u.g]:75,"\ubcf8\ubb38\uc774 \ub108\ubb34 \uae41\ub2c8\ub2e4. \uc785\ub825\uc744 \uc720\uc9c0\ud588\uc73c\ub2c8 \uae38\uc774\ub97c \uc904\uc5ec \uc8fc\uc138\uc694.":76,"\uae30\ub85d \ud06c\uae30\uac00 \ub108\ubb34 \ud07d\ub2c8\ub2e4. \uc785\ub825\uc744 \uc720\uc9c0\ud588\uc73c\ub2c8 \uae38\uc774\ub97c \uc904\uc5ec \uc8fc\uc138\uc694.":77,"\uc11c\ubc84\uc5d0 \uc800\uc7a5\ud588\uc2b5\ub2c8\ub2e4. \uc5f0\ub3d9 \uae30\ub85d \ud654\uba74\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.":78,"\uc218\uc815 \ucda9\ub3cc\uc785\ub2c8\ub2e4. \uc785\ub825\uc744 \ubcf5\uc0ac\ud574 \ubcf4\uc874\ud55c \ud6c4 \ubaa9\ub85d\uc744 \ub2e4\uc2dc \uc870\ud68c\ud574 \uc8fc\uc138\uc694.":79,"\uc800\uc7a5\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc785\ub825\uc744 \ubcf4\uc874\ud588\uc2b5\ub2c8\ub2e4. \uac19\uc740 \uc694\uccad\uc73c\ub85c \uc7ac\uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694.":80,"\ube0c\ub77c\uc6b0\uc800 \uc800\uc7a5\uc18c\ub97c \uc5f4\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc6d0\ubcf8\uc744 \ucd08\uae30\ud654\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.":81,[u.W]:82,"\uc571\uc758 \uc0c1\uc9d5 \uc0ac\uc6a9 \ubc94\uc704\ub97c \ud655\uc778\ud560 \uc218 \uc5c6\uc5b4 \uc120\ud0dd\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.":83,[u.x]:84,"\uae30\uae30\uc5d0 \ubcf4\uad00\ud588\uc2b5\ub2c8\ub2e4. \ub0a8\uc740 \ub3d9\uae30\ud654\ub294 \uc790\ub3d9\uc73c\ub85c \uacc4\uc18d\ud569\ub2c8\ub2e4.":85,"\ucda9\ub3cc\ud55c \uc591\ucabd \uae30\ub85d\uc744 \ubcf4\uc874\ud588\uc2b5\ub2c8\ub2e4. \uc790\ub3d9\uc73c\ub85c \ub36e\uc5b4\uc4f0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.":86,"\uae30\uae30 \ubcf4\uad00\uacfc \uc11c\ubc84 \ud655\uc778\uc744 \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.":87,"\uc624\ud504\ub77c\uc778 \uae30\uae30 \ubcf4\uad00 \ubaa8\ub4dc\uc785\ub2c8\ub2e4. \uc11c\ubc84 \uc804\uc1a1\uc740 \uacc4\uc815 \ud655\uc778 \ud6c4 \uc7ac\uac1c\ud569\ub2c8\ub2e4.":88,"\uc5f0\uacb0\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uae30\uae30\uc5d0 \ubcf4\uad00\ud55c \uae30\ub85d\uacfc \uc804\uc1a1 \ub300\uae30\ub294 \uc720\uc9c0\ub429\ub2c8\ub2e4.":89,[u.d]:90,"\uae30\uae30\uc5d0 \uc800\uc7a5\ud588\uc2b5\ub2c8\ub2e4. \uc804\uc1a1 \ub300\uae30\ub294 \uc5f0\uacb0 \ud6c4 \uac19\uc740 \uc694\uccad\uc73c\ub85c \ucc98\ub9ac\ud569\ub2c8\ub2e4.":91,"\uae30\uae30 \uc800\uc7a5\uc744 \uc644\ub8cc\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc785\ub825\uc740 \ud654\uba74\uc5d0 \uc720\uc9c0\ud569\ub2c8\ub2e4.":92}
B.YP=new A.Y(B.Ce,["NoveraFlow sync test","NoveraFlow web","Home","Memo","Records","Maeumgyeol","Search","Settings","App","Sign out","Today's journal","One line is enough.","Take your time. Keep your own pace.","Sign in with the approved NoveraFlow Test account. Use synthetic text only.","Isolated development workspace. App record sync is unavailable.","Writing, viewing, editing, searching text entries and basic sync are free. Clearing browser storage can remove local copies. Offline transfers resume after online account verification.","Checking your account.","Sign in to access your records.","Your account is verified.","We could not verify your account. Please sign in again.","Account verification is delayed. Your draft is preserved. Please try again.","Check test authentication and the approved web callback first.","We could not connect. Please refresh in a moment.","Your journal, continued","New here? Continuing with Google or Apple creates your account. You do not need to sign up in the mobile app first.","Continue with Google","Continue with Apple","Check account again","The records service is unavailable. Writing, saving and searching are disabled even if you are signed in. Please do not enter personal records.","Records and sync","Use your existing account records and save status. Sync does not replace a backup.","Backup and restore","Backup and restore are not available on the web. Use the mobile app for backup and restore.","A separate memo editor is not available on the web. Memos saved with entries appear in record details.","Maeumgyeol conversations are available in supported mobile apps. Conversations are not available on the web.","Back to records","You have unsaved changes","Opening another record discards your unsaved changes.","Keep editing","Open another record","Write an entry","Edit entry","New entry","Editing entry","Basic symbols","None selected","No symbol","Symbol changes are temporarily unavailable because we could not verify your app permissions.","Your changed symbol is preserved in the draft. You can restore the original symbol to save the text.","Restore original symbol","Existing selected phrases and memos are preserved.","Entry text","Write a thought you want to keep.","Enter some text to sync your entry.","Save to device and sync","Save","Retry the same request","New entry","Search entries","Find a thought you kept.","Search / refresh","The original and both conflicting versions are preserved on this device. Nothing is overwritten automatically.","Search results","My records","No entries to show yet. Start with one line.","Load more","Entry details","Symbol","Pending transfers","Preserved conflicts","entries","Created","Selected phrase","Records loaded from the server.","Could not load records. Your draft is preserved.","Could not verify symbol permissions. Nothing was saved; your draft is preserved.","The text is too long. Your draft is preserved; please shorten it.","The entry is too large. Your draft is preserved; please shorten it.","Saved to the server. Check the linked records screen.","Conflicting changes. Copy your draft before refreshing the list.","Could not save. Your draft is preserved. Retry the same request.","Could not open browser storage. Existing data will not be reset.","Could not save your draft on this device. Copy it before closing this screen.","Cannot select a symbol until app permissions are verified.","Transfers paused because symbol permissions could not be verified. Pending entries are preserved.","Saved on this device. Remaining sync continues automatically.","Both conflicting entries are preserved. Nothing is overwritten automatically.","Saved on this device and confirmed by the server.","Offline: keeping records on this device. Transfers resume after account verification.","Could not connect. Local records and pending transfers are preserved.","Saving paused because symbol permissions could not be verified. Drafts and pending entries are preserved.","Saved on this device. Pending transfers resume with the same request after reconnecting.","Could not finish saving on this device. Your draft remains on screen."],t.w)
